setcpm(84/4)

// A function names the koto's touch once; the decay d has a default
const koto = (x, d = .6) => x.s("triangle").timbre("bright").attack(.002).decay(d).sustain(0).release(d)
// A builder makes a whole phrase from a starting degree
const phrase = (start) => n(run(5).add(start)).scale("D:hirajoshi").transpose(12)

// Rising and falling through five notes of the hirajoshi scale
pluck: phrase(0).palindrome().koto().pan(.35).room(.5).gain(.3)
// A second koto answers two degrees higher, now and then an octave up
answer: phrase(2).late(1/8).koto(1.2).rarely(x => x.octave(1)).seed("koi")
  .pan(.65).delay(.3).delaytime(3/8).room(.5).gain(.18)

// A shakuhachi drifts above in long, overlapping breaths
flute: n("<4 [5@3 3] 2 ~ 6 [5@3 4] 3 ~>").scale("D:hirajoshi").transpose(12)
  .s("sine").timbre("hollow").mono(1).glide(.15).vib(4.5).vibdepth(.25)
  .attack(.3).sustain(.7).release(1).legato(1.2).room(.8).gain(.24)

// Water, a low fifth and a temple bell every eight bars
stream: s("stream").slow(4).azimuth(-40).distance(3).gain(.2)
drone: note("[d2,a2]").slow(4).s("sine").attack(2).sustain(1).release(3).gain(.18)
bell: note("<d3 ~ ~ ~ ~ ~ ~ ~>").s("sine").fm(3).fmh(2.76)
  .decay(4).sustain(0).release(4).space("hall").gain(.18)

setcpm(76/4)

// One theme, written as scale degrees
const theme = n("<[0 2 4 2] [5 4 2 0] [1 3 5 3] [4@2 2 0]>")
// An entry waits some cycles, moves by some degrees, then picks the scale
const entry = (x, wait, step) => x.late(wait).add(step).scale("C:major")
// A bowed string, with a default brightness
const bowed = (x, bright = 2400) => x.s("sawtooth").vib(5.5).vibdepth(.1).attack(.04).sustain(.6).release(.2).lpf(bright)

// Three entries, a cycle apart, each at its own height
first: theme.entry(0, 7).bowed(3200).pan(.3).room(.5).gain(.22)
second: theme.entry(1, 9).bowed().pan(.7).room(.5).gain(.2)
third: theme.entry(2, 4).bowed(1800).room(.5).gain(.18)

// The ground bass an octave down; on every fourth cycle it doubles its notes
ground: n("<0 5 1 4>").scale("C:major").octave(-1)
  .s("sawtooth").lpf(700).attack(.04).sustain(.5).release(.3).legato(.9)
  .lastOf(4, x => x.ply(2)).room(.4).gain(.3)

// A harpsichord taps the off-beats, each tap trailing fading echoes
harpsichord: n("<[0,2,4] [5,7,9] [1,3,5] [4,6,8]>").scale("C:major").struct("~ x ~ x")
  .s("square").pw(.15).decay(.15).sustain(0).echo(3, 1/8, .5).room(.3).gain(.1)

setcpm(128/4)

// A function can take another function: play the pattern and a changed copy together
const twice = (x, f) => stack(x, x.apply(f))
// A ratchet repeats each step, a little quieter; n defaults to 2
const ratchet = (x, n = 2) => x.ply(n).gain(.5)

kick: s("bd*4").shape(.2).gain(.8)
// As a partial application: every fourth bar the claps ratchet in threes
clap: s("~ cp ~ cp").every(4, ratchet(3)).room(.25).gain(.45)
// The hats and a copy a sixteenth late, quieter and to the right
hats: s("hh*8").hpf(7000).gain(.3).twice(x => x.late(1/16).gain(.12).pan(.7))
// chunk hurries a moving quarter of each bar
rim: s("rim*8").chunk(4, x => x.hurry(2)).pan(.35).gain(.22)

// The acid line: sub drops it an octave, accents fall off the beat, notes stay short
acid: n("0 0 7 0 3 0 10 5").scale("C:minor").sub(12)
  .s("sawtooth").lpf(perlin.range(400, 2400)).lpq(10).lpenv(2).lpdecay(.1)
  .gain(.4).accent("~ ~ x ~ ~ ~ x ~").legato(.5)
  .sometimesBy(.2, x => x.apply(ratchet)).seed("303")

// Chords on a euclidean rhythm, with an octave ghost three sixteenths behind
chords: note("[c3,eb3,g3,bb3]").struct("x(3,8)")
  .s("sawtooth").unison(3).detune(.2).lpf(1800).decay(.2).sustain(0).gain(.2)
  .twice(x => x.late(3/16).octave(1).gain(.08))
  .room(.4)

setcpm(172/4)

// One break, written once
const amen = s("bd ~ bd ~ sd ~ ~ sd ~ sd bd ~ sd ~ [~ bd] sd, hh*16")
// On the last bar of every four, hold the first quarter of the break
const stutterEnd = (x) => x.lastOf(4, y => y.linger(.25))

// Some bars are dealt back in a new order (shuffle), some rebuilt with repeats (scramble)
breaks: amen.someCyclesBy(.4, x => x.shuffle(8)).someCyclesBy(.2, x => x.scramble(16))
  .stutterEnd().seed("surgery").gain(.6)

// Ghost rims: a moving quarter, counted from the end, runs at double speed
ghosts: s("rim*16?0.3").chunkBack(4, x => x.fast(2)).seed("ghost").hpf(2000).gain(.15)

// A reese bass, each note pushed half-way into its step
reese: note("<e1 e1 c1 d1>").struct("x ~ ~ x ~ ~ x ~").press()
  .s("sawtooth").unison(4).detune(.4).lpf(sine.range(200, 700).slow(4)).lpq(3)
  .attack(.02).sustain(.8).release(.2).gain(.38)

// Stabs that brak squashes into a syncopated half every other bar
stabs: note("<[e3,g3,b3,d4] [c3,e3,g3,b3]>").struct("x ~ x ~").brak()
  .s("sawtooth").unison(3).detune(.2).lpf(2200).decay(.3).sustain(0).room(.5).gain(.2)

// Rhodes arpeggios that leap an octave in the first half of each bar
keys: n("0 2 4 6 7 6 4 2").add("<0 0 -2 -1>").scale("E:minor").transpose(12)
  .within(0, .5, x => x.octave(1))
  .s("sine").fm(1).fmh(2).decay(.25).sustain(0)
  .delay(.4).delaytime(3/16).delayfeedback(.45).pan(sine.slow(4)).gain(.18)

setcpm(132/4)

// Hungarian minor: the raised fourth makes two augmented seconds
const fiddle = (x) => x.scale("A:hungarian minor").transpose(12).s("sawtooth").vib(6).vibdepth(.12).lpf(3200).attack(.02).sustain(.6).release(.1)
const cimbalom = (x) => x.scale("A:hungarian minor").s("sine").fm(2.5).fmh(3).decay(.25).sustain(0).release(.3)

// The fiddle tune; the last phrase of every four jumps an octave
violin: n("<[0 1 2 3 4@2 3 2] [4 5 6 7 6@2 4 2] [3 2 1 0 -1@2 0 1] [2 1 0 -1 0@4]>").fiddle()
  .lastOf(4, x => x.octave(1)).pan(.6).room(.4).gain(.24)

// The cimbalom ripples under it
cimb: n("0 2 4 2 7 4 2 4").add("<0 0 3 -1>").cimbalom().pan(.35).room(.3).gain(.2)

// Oom-pah: short bass notes, chords louder on the last beat of each bar
bass: note("<a1 a1 d2 e2>").struct("x ~ x ~").legato(.4)
  .s("triangle").decay(.3).sustain(.3).release(.1).gain(.42)
chords: note("<[c3,e3,a3] [c3,e3,a3] [d3,f3,a3] [d3,e3,g#3,b3]>").struct("~ x ~ x").accent("~ ~ ~ x")
  .s("triangle").timbre("bright").decay(.15).sustain(0).gain(.18)

// The band rushes the last bar of every eight: hurry doubles speed and pitch
drums: s("bd ~ bd ~, ~ rim ~ rim").lastOf(8, x => x.hurry(2)).gain(.4)

setcpm(72/4)

// No half steps anywhere: the whole-tone scale floats with no home note
const dream = n("0 1 2 3 4 5 6 7").scale("C:whole tone")
const glassy = (x) => x.s("triangle").timbre("glass").decay(.4).sustain(0).release(.8)
// A halo: an octave above, quiet, to the right
const halo = (x) => x.add(12).gain(.08).pan(.8)

// The run with its halo; within makes the second half answer with the first half backwards
upper: dream.transpose(12).glassy().gain(.2).superimpose(halo).within(.5, 1, x => x.rev())
  .delay(.35).delaytime(3/8).delayfeedback(.4).room(.6)

// zoom stretches the middle half of the run across the whole bar
middle: dream.zoom(.25, .75).glassy().pan(.3).room(.6).gain(.16)

// compress squeezes the whole run into the first half of the bar, an octave down
low: dream.compress(0, .5).octave(-1).s("sine").fm(1.5).fmh(2)
  .decay(.3).sustain(0).room(.6).gain(.2)

// fastGap plays eight ticks in the first half and leaves the second half silent
ticks: s("tick*8").fastGap(2).gain(.1)

// Augmented chords, and a bass walking the augmented scale
pad: note("<[c3,e3,g#3] [d3,f#3,a#3]>").slow(2).s("sawtooth").unison(3).detune(.25)
  .attack(2).release(3).lpf(1100).room(.8).size(.9).gain(.12)
bass: n("<0 1 2 3>").slow(2).scale("C:augmented").octave(-1)
  .s("sine").attack(.5).sustain(.8).release(1.5).gain(.28)

setcpm(100/4)

// G lydian dominant: a raised fourth and a flat seventh, bright and bluesy at once
// swingBy(1/3, 4) delays every second eighth by a third of a beat
drums: s("bd ~ ~ bd ~ ~ bd ~, ~ sd ~ sd, hh*8").swingBy(1/3, 4).gain(.6)

// The bass sits a hair behind the beat (nudge is in seconds) and plays short (legato)
bass: n("0 ~ 0 4 ~ 6 7 ~").scale("G:lydian dominant").sub(24)
  .s("sawtooth").lpf(800).lpenv(2).lpdecay(.1)
  .legato(.4).nudge(.015).accent("x ~ ~ x ~ ~ x ~").swingBy(1/3, 4).gain(.4)

// Chords pushed half-way into each step: G13 with the raised eleventh
keys: note("<[f3,b3,c#4,e4] [f3,a3,c#4,e4]>").struct("x ~ ~ x ~ ~ x ~").press()
  .s("sine").fm(1.1).fmh(2).decay(.5).sustain(.2).release(.3).lpf(2400).pan(.4).gain(.24)

// The lead: rarely a stutter, almost always a little echo, and a fifth above as a horn
lead: n("<[4 5 6 7] [9 7 6 4] [3 4 6 3] [4@4]>").scale("G:lydian dominant").transpose(12)
  .s("square").pw(.3).lpf(2800).attack(.01).decay(.2).sustain(.4).release(.1).gain(.18)
  .almostNever(x => x.ply(2)).almostAlways(x => x.delay(.3).delaytime(3/16))
  .superimpose(x => x.add(7).gain(.08)).seed("lift").pan(.6)

setcpm(60/4)

// The egyptian pentatonic: fourths and fifths and no thirds, open and unresolved
// A singer is a function: the voice type has a default, the phrasing is shared
const singer = (x, type = "alto") => x.s("voice").voicetype(type).mono(1).vglide(.1).attack(.1).release(.8)

// The syllables use the same weights as the notes, so each lands on its note
solo: n("<[0@3 1 2@4] [4@2 3 2 1@4] [2@3 3 4@2 5 4] [3@6 ~@2]>").scale("D:egyptian").transpose(12)
  .singer().syl("<[ya@3 ha la@4] [ma@2 ni ra so@4] [ka@3 li ma@2 na o] [hu@6 ~@2]>")
  .space("hall").gain(.32)

// A tenor answers below, with the same function and a different voice
tenor: n("<0 [2 1] 3 [2 0]>").scale("D:egyptian").singer("tenor")
  .syl("<oh [ah oh] oo [ah oh]>").space("hall").gain(.22)

// A choir on open chords, a hum with an overtone, a frame drum and the desert wind
choir: note("<[d3,a3,d4] [c3,g3,c4] [e3,a3,e4] [d3,g3,a3]>").slow(2)
  .s("choir").syl("<oo ah>").attack(2).release(3).space("church").gain(.2)
hum: note("d2").slow(8).s("hum").overtone(6).gain(.14)
frame: s("lt ~ ~ lt ~ ~ lt ~, ~ ~ rim ~").room(.4).gain(.3)
wind: s("wind").slow(8).intensity(.25).gain(.08)

setcpm(90/4)

// A melody drawn from the in sen scale, one seeded draw per eighth note
const melody = n(irand(8).segment(8)).scale("E:in sen").transpose(12)
const bloom = (x) => x.s("triangle").timbre("soft").attack(.005).decay(.8).sustain(.1).release(1).room(.6)

// Two hands share the melody: degradeBy drops some notes, undegradeBy keeps only some
left: melody.degradeBy(.5).bloom().often(x => x.octave(-1)).seed("garden").pan(.3).gain(.24)
right: melody.undegradeBy(.4).bloom().rarely(x => x.octave(1)).seed("garden").pan(.7).gain(.2)

// Bells decide once per cycle whether to hurry
bells: note("<b4 ~ e5 ~>").s("sine").fm(2).fmh(2.76).decay(2).sustain(0).release(2)
  .someCyclesBy(.3, x => x.fast(2)).seed("bells").space("hall").gain(.12)

// Percussion: almost never a roll, some cycles played backwards
perc: s("rim*8?0.5, ~ lt").almostNever(x => x.ply(4)).someCycles(x => x.rev())
  .seed("perc").room(.3).gain(.22)

// A drone breathing through smooth noise, and a stream
drone: note("[e2,b2]").slow(4).s("sawtooth").unison(2).detune(.15)
  .lpf(perlin.range(300, 900).slow(4)).attack(2).sustain(1).release(3).gain(.14)
stream: s("stream").slow(4).distance(4).gain(.16)
